import type { IConnector } from '../connector'
import { XMLParser } from 'fast-xml-parser'
import type { Logger } from '@servicenow/sdk-build-core'

export class Uninstaller {
    constructor(
        private connector: IConnector,
        private logger: Logger
    ) {}

    async process(scope: string, scopeId: string, isStoreApp: boolean): Promise<void> {
        this.logger.info(`Uninstalling application with scope ID: ${scopeId}`)

        // set the current application scope
        await this.connector.setCurrentApplication(scopeId)
        // uninstall the application
        const response = await this.connector.uninstallApplication(scopeId, isStoreApp)
        if (!response.ok) {
            throw new Error(`Failed to uninstall application: ${response.statusText}`)
        }
        const xml = await parseXml(await response.text())
        const progressID = xml['xml']['@_answer']
        await this.monitorStatus(scope, scopeId, progressID)

        this.logger.info(`Successfully uninstalled application with scope ID: ${scopeId}`)
    }
    private async monitorStatus(scope: string, scopeId: string, progressID: string): Promise<void> {
        if (!(await this.monitorProgress(progressID))) {
            throw new Error('App uninstall is taking too long or failed, please check the instance logs')
        }
        if (!(await this.monitorMutexRelease())) {
            throw new Error('Error while waiting for app uninstall to complete, please check the instance logs')
        }

        const appInfo = await this.connector.getScopeInfo(scope, scopeId)

        if (appInfo && appInfo.appId) {
            if (!appInfo.active) {
                return
            }
            throw new Error('Failed to uninstall application, sys_scope record still exists')
        }
    }

    private async monitorProgress(progressID: string): Promise<boolean> {
        let attempt = 0
        while (true) {
            const res = await this.connector.getProgress(progressID)

            if (
                (res.status === TrackerStatus.SUCCESSFUL && res.percent_complete === 100) ||
                res.status_message.includes('Failed to completely delete application') ||
                res.status_message.includes('The store application was deactivated')
            ) {
                if (res.status === TrackerStatus.ERROR) {
                    this.logger.warn(
                        'Deleted application and metadata. Some ACL protected metadata may remain. For a truly clean install, please delete/uninstall app from instance UI'
                    )
                } else {
                    this.logger.info(res.status_message)
                }
                return true
            } else if (
                res.status !== TrackerStatus.PENDING &&
                res.status !== TrackerStatus.RUNNING &&
                res.status !== TrackerStatus.SUCCESSFUL
            ) {
                this.logger.error(res.status_message)
                return false
            }

            // Query instance once per second
            await new Promise((resolve) => setTimeout(resolve, 1000))

            attempt += 1
            // Log tracker status every 30 seconds if tracker hasn't completed
            if (attempt % 30 === 0 && res.status_message) {
                this.logger.info('Uninstall pending, waiting on ' + res.status_message)
            }
        }
    }

    private async monitorMutexRelease(): Promise<boolean> {
        let attempt = 0
        while (true) {
            const r = await this.connector.getUpdateMutex()

            if (r) {
                this.logger.debug('Update-Mutex released: proceeding with install')
                return true
            }

            // Query instance once per second
            await new Promise((resolve) => setTimeout(resolve, 1000))
            attempt += 1
            if (attempt === 30) {
                this.logger.error(
                    'Update-Mutex was not released within appropriate time\n\t' +
                        'Either this operation is taking a while or another CICD operation may be underway on the instance.\n\t' +
                        'Please try again when sys_mutex table indicates Update-Mutex is released'
                )
                return false
            }
            // Log tracker status every 15 seconds if tracker hasn't completed
            if (attempt % 15 === 0) {
                this.logger.debug('Uninstall pending, waiting on Update-Mutex release')
            }
        }
    }
}

function parseXml(xmlString: string) {
    const parser = new XMLParser({
        ignoreAttributes: false,
        ignoreDeclaration: false,
    })
    return parser.parse(xmlString)
}

export const TrackerStatus = {
    PENDING: '0',
    RUNNING: '1',
    SUCCESSFUL: '2',
    ERROR: '3',
}
